class Solution {
  public int[] recoverOrder(int[] order, int[] friends) {
    Set<Integer> set = new HashSet<>();
    for (int f : friends) set.add(f);
    int[] ans = new int[friends.length];
    int k = 0;
    for (int id : order) {
      if (set.contains(id)) ans[k++] = id;
    }
    return ans;
  }
}
